#!/usr/bin/env bash
# Question 1: app.${Q1_NS}.lab unreachable through the Gateway. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get ingressclass traefik >/dev/null 2>&1 && kubectl get gatewayclass traefik >/dev/null 2>&1 || {
  echo "this cluster image has no Traefik or Gateway API: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "${Q1_NS}-gw" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-gw" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}-gw' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl create namespace "${Q1_NS}-backend" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-backend" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}-backend' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
openssl req -x509 -newkey rsa:2048 -nodes -days 30 -subj "/CN=app.${Q1_NS}.lab" -addext "subjectAltName=DNS:app.${Q1_NS}.lab" -keyout "/var/tmp/cka-q1.tls.key" -out "/var/tmp/cka-q1.tls.crt" 2>/dev/null
kubectl -n "${Q1_NS}-gw" create secret tls edge-tls --cert="/var/tmp/cka-q1.tls.crt" --key="/var/tmp/cka-q1.tls.key" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q1_NS}-backend" create deployment shop --image=nginx:1.27-alpine --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q1_NS}-backend" expose deployment shop --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl apply -f - <<< '{"apiVersion":"gateway.networking.k8s.io/v1","kind":"Gateway","metadata":{"name":"edge","namespace":"'"${Q1_NS}"'-gw"},"spec":{"gatewayClassName":"traefik","listeners":[{"name":"http","protocol":"HTTP","port":8000,"hostname":"app.'"${Q1_NS}"'.lab","allowedRoutes":{"namespaces":{"from":"All"}}},{"name":"https","protocol":"HTTPS","port":8443,"hostname":"app.'"${Q1_NS}"'.lab","tls":{"mode":"Terminate","certificateRefs":[{"kind":"Secret","name":"edge-tls"}]},"allowedRoutes":{"namespaces":{"from":"All"}}}]}}' >/dev/null
kubectl apply -f - <<< '{"apiVersion":"gateway.networking.k8s.io/v1beta1","kind":"ReferenceGrant","metadata":{"name":"allow-shop-routes","namespace":"'"${Q1_NS}"'-backend"},"spec":{"from":[{"group":"gateway.networking.k8s.io","kind":"HTTPRoute","namespace":"'"${Q1_NS}"'"}],"to":[{"group":"","kind":"Service"}]}}' >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: shop
  namespace: ${Q1_NS}
spec:
  parentRefs:
    - name: edge
      namespace: ${Q1_NS}-gw
  hostnames: [app.${Q1_NS}.lab]
  rules:
    - backendRefs:
        - name: shop
          namespace: ${Q1_NS}-backend
          port: 80
EOF
kubectl -n "${Q1_NS}-backend" rollout status deployment/shop --timeout=180s >/dev/null
for _ in $(seq 1 60); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } && break; sleep 2; done
{ curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; }

case "${Q1_FAULT}" in
  allowed-routes-same)
    kubectl -n "${Q1_NS}-gw" patch gateway edge --type=json -p '[{"op":"replace","path":"/spec/listeners/0/allowedRoutes/namespaces/from","value":"Same"},{"op":"replace","path":"/spec/listeners/1/allowedRoutes/namespaces/from","value":"Same"}]'
    ;;
  listener-hostname)
    kubectl -n "${Q1_NS}-gw" patch gateway edge --type=json -p '[{"op":"replace","path":"/spec/listeners/0/hostname","value":"app.'"${Q1_NS}"'.local"},{"op":"replace","path":"/spec/listeners/1/hostname","value":"app.'"${Q1_NS}"'.local"}]'
    ;;
  listener-port)
    kubectl -n "${Q1_NS}-gw" patch gateway edge --type=json -p '[{"op":"replace","path":"/spec/listeners/0/port","value":8080}]'
    ;;
  https-listener-secret)
    kubectl -n "${Q1_NS}-gw" patch gateway edge --type=json -p '[{"op":"replace","path":"/spec/listeners/1/tls/certificateRefs/0/name","value":"edge-tls-2024"}]'
    ;;
  gatewayclass-missing)
    kubectl -n "${Q1_NS}-gw" delete gateway edge --wait=true
    kubectl apply -f - <<< '{"apiVersion":"gateway.networking.k8s.io/v1","kind":"Gateway","metadata":{"name":"edge","namespace":"'"${Q1_NS}"'-gw"},"spec":{"gatewayClassName":"traefik-internal","listeners":[{"name":"http","protocol":"HTTP","port":8000,"hostname":"app.'"${Q1_NS}"'.lab","allowedRoutes":{"namespaces":{"from":"All"}}},{"name":"https","protocol":"HTTPS","port":8443,"hostname":"app.'"${Q1_NS}"'.lab","tls":{"mode":"Terminate","certificateRefs":[{"kind":"Secret","name":"edge-tls"}]},"allowedRoutes":{"namespaces":{"from":"All"}}}]}}'
    ;;
  route-parent-namespace)
    kubectl -n "${Q1_NS}" patch httproute shop --type=json -p '[{"op":"remove","path":"/spec/parentRefs/0/namespace"}]'
    ;;
  route-backend-namespace)
    kubectl -n "${Q1_NS}" patch httproute shop --type=json -p '[{"op":"remove","path":"/spec/rules/0/backendRefs/0/namespace"}]'
    ;;
  reference-grant-missing)
    kubectl -n "${Q1_NS}-backend" delete referencegrant allow-shop-routes
    ;;
  reference-grant-from)
    kubectl -n "${Q1_NS}-backend" patch referencegrant allow-shop-routes --type=json -p '[{"op":"replace","path":"/spec/from/0/namespace","value":"'"${Q1_NS}"'-gw"}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

case "${Q1_FAULT}" in
  allowed-routes-same)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  listener-hostname)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  listener-port)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  https-listener-secret)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  gatewayclass-missing)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  route-parent-namespace)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  route-backend-namespace)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  reference-grant-missing)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
  reference-grant-from)
    for _ in $(seq 1 30); do { curl -s -m 5 -H 'Host: app.${Q1_NS}.lab' http://controlplane:30080/ | grep -q 'Welcome to nginx' && curl -sk -m 5 --resolve app.${Q1_NS}.lab:30443:$(getent hosts controlplane | awk '{print $1}') https://app.${Q1_NS}.lab:30443/ | grep -q 'Welcome to nginx'; } || exit 0; sleep 2; done
    echo "app.${Q1_NS}.lab still works over HTTP and HTTPS" >&2
    exit 1
    ;;
esac
